import { Search, Bell, ShoppingCart, ChevronDown } from 'lucide-react';
import { useSearch } from '../context/SearchContext';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';

export const Topbar = () => {
  const { searchQuery, setSearchQuery } = useSearch();
  const { cart, setIsCartOpen } = useCart();
  const { user } = useAuth();

  return (
    <header className="h-20 bg-white border-b border-gray-200 flex items-center justify-between px-8 sticky top-0 z-10">
      <div>
        <h2 className="text-2xl font-bold text-gray-900">Marketplace</h2>
        <p className="text-sm text-gray-500 font-medium mt-0.5">Fresh Produce. Direct from Farmers.</p>
      </div>

      <div className="flex-1 max-w-2xl mx-12">
        <div className="relative group">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-farmGreen transition-colors" size={20} />
          <input 
            type="text" 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search for produce (e.g. tomatoes, maize, cassava...)" 
            className="w-full pl-12 pr-4 py-2.5 bg-gray-50 border border-transparent rounded-full text-sm focus:bg-white focus:border-farmGreen focus:outline-none focus:ring-4 focus:ring-farmGreen/10 transition-all"
          />
        </div>
      </div>

      <div className="flex items-center gap-6">
        {/* Cart Button */}
        <button 
          onClick={() => setIsCartOpen(true)}
          className="relative p-2 text-gray-500 hover:text-farmGreen transition-colors rounded-full hover:bg-gray-100"
        >
          <ShoppingCart size={24} />
          {cart.length > 0 && (
            <span className="absolute top-0 right-0 bg-farmGreen text-white text-[10px] font-bold rounded-full h-4 w-4 flex items-center justify-center border-2 border-white">
              {cart.length}
            </span>
          )}
        </button>

        <button className="relative p-2 text-gray-500 hover:text-gray-900 transition-colors rounded-full hover:bg-gray-100">
          <Bell size={24} />
        </button>
        
        <div className="flex items-center gap-3 cursor-pointer hover:bg-gray-50 p-1.5 rounded-lg transition-colors border border-transparent hover:border-gray-200">
          <div className="w-10 h-10 rounded-full bg-farmGreen text-white flex items-center justify-center font-bold">
            {user?.name.charAt(0)}
          </div>
          <div className="hidden md:block">
            <p className="text-sm font-bold text-gray-900">{user?.name}</p>
            <p className="text-xs text-gray-500 font-medium capitalize">{user?.role}</p>
          </div>
          <ChevronDown size={16} className="text-gray-400 ml-1" />
        </div>
      </div>
    </header>
  );
};
